create function app.private_invoice_numeric_candidates(p_term text,p_enumeration boolean) returns setof text
language plpgsql immutable set search_path='' as $$
declare prepared text:=app.private_invoice_number_scalar(p_term); keys text[];parts text[];groups text[];i integer;j integer;k integer;candidate text;rendered text;
begin
 if p_enumeration then
  rendered:=app.private_invoice_collection_rendering(p_term);
  if strpos(rendered,'|')>0 then for candidate in select unnest(string_to_array(rendered,'|')) loop return query select * from app.private_invoice_numeric_candidates(candidate,true);end loop;return;end if;
  if rendered<>app.private_invoice_normalize(p_term) then if strpos(p_term,'/')=0 then return query select * from app.private_invoice_number_aliases(p_term);return query select * from app.private_invoice_word_number_aliases(p_term);end if;return query select * from app.private_invoice_numeric_candidates(rendered,true);return;end if;
  if prepared ~ '[a-z]' then for candidate in select regexp_split_to_table(prepared,',') loop return query select * from app.private_invoice_number_aliases(candidate);return query select * from app.private_invoice_word_number_aliases(candidate);end loop;end if;
 end if;
 if length(prepared)>3989 and prepared ~ '^[0-9][0-9.,'' ]*([kmb])?$' then return query select * from app.private_invoice_numeric_run_keys(prepared);return;end if;
 keys:=array(select distinct x from app.private_invoice_number_aliases(p_term) x where length(x)<=4000);
 return query select unnest(keys);
 if prepared !~ '^[0-9][0-9.,'' ]*([kmb])?$' then return;end if;
 parts:=regexp_split_to_array(prepared,', *');
 if length(prepared)>3989 or cardinality(regexp_split_to_array(prepared,'[, ]+'))>32 then return query select * from app.private_invoice_numeric_run_keys(prepared);return;end if;
 if cardinality(parts)<=32 and cardinality(keys)>0 and not coalesce(p_enumeration,false) and app.private_invoice_normalize(p_term) !~ ', +' then return;end if;
 if cardinality(parts)>1 then
  -- Keep the graph itself plus its atomic members. Expanding every bounded
  -- subwindow here made cold source writes proportional to n * window.
  return query select * from app.private_invoice_numeric_run_keys(prepared);
  for i in 1..cardinality(parts) loop
   return query select * from app.private_invoice_numeric_candidates(parts[i],false);
   -- Adjacent decimal/grouping edges are linear; longer paths stay compact.
   if i<cardinality(parts) then return query select * from app.private_invoice_number_aliases(parts[i]||','||parts[i+1]);end if;
  end loop;return;
 end if;
 if cardinality(keys)>0 then return;end if;
 groups:=regexp_split_to_array(prepared,' +');i:=1;
 while i<=cardinality(groups) loop
  j:=cardinality(groups);
  while j>=i loop
   keys:=array(select x from app.private_invoice_number_aliases(array_to_string(groups[i:j],' ')) x);
   exit when cardinality(keys)>0;j:=j-1;
  end loop;
  if j<i then i:=i+1;continue;end if;
  return query select unnest(keys);i:=j+1;
 end loop;
end $$;
revoke all on function app.private_invoice_numeric_candidates(text,boolean) from public,anon,authenticated,service_role;

-- The same strict group grammar as JS: one atom, tens+unit, or a hundred group.
create function app.private_invoice_group_number(words text[]) returns numeric
language plpgsql immutable set search_path='' as $$
declare small jsonb:='{"zero":"0","one":"1","two":"2","three":"3","four":"4","five":"5","six":"6","seven":"7","eight":"8","nine":"9","ten":"10","eleven":"11","twelve":"12","thirteen":"13","fourteen":"14","fifteen":"15","sixteen":"16","seventeen":"17","eighteen":"18","nineteen":"19","twenty":"20","thirty":"30","forty":"40","fifty":"50","sixty":"60","seventy":"70","eighty":"80","ninety":"90"}'::jsonb; n integer:=cardinality(words); h integer; a numeric; b numeric;
begin
  if n=0 then return 0;end if;
  h:=array_position(words,'hundred');
  if h is not null then
    if array_position(words[h+1:n],'hundred') is not null then return null;end if;
    a:=case when h=1 then 1 else app.private_invoice_group_number(words[1:h-1]) end;
    b:=app.private_invoice_group_number(words[h+1:n]);
    return case when a>0 and a<100 and b>=0 and b<100 then a*100+b else null end;
  end if;
  if n=1 then
    if small ? words[1] then return (small->>words[1])::numeric;end if;
    return (select substring(k from 8)::numeric from app.private_invoice_number_aliases(words[1]) k where k ~ '^number:[0-9]+$' limit 1);
  end if;
  if n<>2 then return null;end if;
  a:=app.private_invoice_group_number(words[1:1]);b:=app.private_invoice_group_number(words[2:2]);
  return case when a between 20 and 90 and mod(a,10)=0 and b>0 and b<10 then a+b else null end;
end $$;
revoke all on function app.private_invoice_group_number(text[]) from public,anon,authenticated,service_role;

create function app.private_invoice_word_number_value(words text[]) returns setof text
language plpgsql immutable set search_path='' as $$
declare
  small jsonb:='{"zero":"0","one":"1","two":"2","three":"3","four":"4","five":"5","six":"6","seven":"7","eight":"8","nine":"9","ten":"10","eleven":"11","twelve":"12","thirteen":"13","fourteen":"14","fifteen":"15","sixteen":"16","seventeen":"17","eighteen":"18","nineteen":"19","twenty":"20","thirty":"30","forty":"40","fifty":"50","sixty":"60","seventy":"70","eighty":"80","ninety":"90"}'::jsonb; scales jsonb:='{"thousand":"1000","lakh":"100000","lac":"100000","million":"1000000","crore":"10000000","billion":"1000000000","trillion":"1000000000000","quadrillion":"1000000000000000","quintillion":"1000000000000000000"}'::jsonb; fractions jsonb:='{"half":"2","halves":"2","quarter":"4","quarters":"4","third":"3","fifth":"5","sixth":"6","seventh":"7","eighth":"8","ninth":"9","tenth":"10"}'::jsonb; magnitudes jsonb:='{"k":"thousand","m":"million","b":"billion"}'::jsonb;modifiers jsonb:='{"quartermore":{"numerator":1,"denominator":4,"base":1},"halfmore":{"numerator":1,"denominator":2,"base":1},"quarterless":{"numerator":-1,"denominator":4,"base":1}}'::jsonb;modifier jsonb;places integer;unit numeric;v numeric;
  factor numeric; split_at integer; base_key text; numerator_key text; head text[]; tail_words text[];
  word text; total numeric:=0; part numeric; tail numeric; last_scale numeric; start_at integer:=1; i integer;
  actual text[]; point integer; cluster numeric; scale_start integer; scale_end integer; magnitude numeric:=0; repeated boolean:=false;
begin
  if cardinality(words)=0 or not exists(select 1 from unnest(words) w where w not in ('and','a')) then return;end if;
  if exists(select 1 from unnest(words) w where magnitudes ? w) and not exists(select 1 from unnest(words) w where not magnitudes ? w and w not in ('and','a')) then return;end if;
  words:=array(select coalesce(magnitudes->>w,w) from unnest(words) with ordinality t(w,n) order by n);
  if cardinality(words)=1 then
    return query select * from app.private_invoice_number_aliases(words[1]);
    if found then return;end if;
  end if;
  if cardinality(words)=1 then return query select * from app.private_invoice_number_aliases(words[1]);if found then return;end if;end if;
  factor:=coalesce((scales->>words[cardinality(words)])::numeric,case when words[cardinality(words)]='hundred' then 100 else 1 end);
  if factor<>1 and exists(select 1 from unnest(words) w where w='point' or fractions ? w or modifiers ? w or strpos(w,'/')>0 or w ~ '^[0-9]+[.,][0-9]+$') then
    return query select 'number:'||trim_scale(substring(alias from 8)::numeric*factor)::text
      from app.private_invoice_word_number_value(words[1:cardinality(words)-1]) alias;return;
  end if;
  if strpos(words[cardinality(words)],'/')>0 then
    head:=case when cardinality(words)=1 then array['zero'] else words[1:cardinality(words)-1] end;
    for base_key in select * from app.private_invoice_word_number_value(head) loop
     for numerator_key in select * from app.private_invoice_number_aliases(words[cardinality(words)]) loop
      return next 'number:'||trim_scale(substring(base_key from 8)::numeric+substring(numerator_key from 8)::numeric)::text;
     end loop;
    end loop;return;
  end if;
  if modifiers ? words[1] then
    modifier:=modifiers->words[1];head:=case when cardinality(words)>1 then words[2:cardinality(words)] else array[(modifier->>'base')] end;
    for base_key in select * from app.private_invoice_word_number_value(head) loop
      places:=greatest(20,length(split_part(substring(base_key from 8),'.',2)));unit:=power(10::numeric,places);
      v:=substring(base_key from 8)::numeric+div((modifier->>'numerator')::numeric*unit,(modifier->>'denominator')::numeric)/unit;
      if v>=0 then return next 'number:'||trim_scale(v)::text;end if;
    end loop;return;
  end if;
  if fractions ? words[cardinality(words)] then
    split_at:=(select max(n) from unnest(words) with ordinality p(w,n) where w='and');
    head:=case when split_at is null then array['zero'] else words[1:split_at-1] end;
    tail_words:=array_remove(words[coalesce(split_at+1,1):cardinality(words)-1],'a');
    if cardinality(tail_words)=0 then tail_words:=array['one'];end if;
    for base_key in select * from app.private_invoice_word_number_value(head) loop
      for numerator_key in select * from app.private_invoice_word_number_value(tail_words) loop
        if numerator_key ~ '^number:[0-9]+$' then return next 'number:'||trim_scale(substring(base_key from 8)::numeric+div(substring(numerator_key from 8)::numeric*power(10::numeric,greatest(20,length(split_part(substring(base_key from 8),'.',2)))),(fractions->>words[cardinality(words)])::numeric)/power(10::numeric,greatest(20,length(split_part(substring(base_key from 8),'.',2)))))::text;end if;
      end loop;
    end loop;return;
  end if;
  point:=array_position(words,'point');
  if point is not null then
    tail_words:=words[point+1:cardinality(words)];
    if cardinality(tail_words)=0 or exists(select 1 from unnest(tail_words) w where w !~ '^[0-9]+$' and (not small ? w or (small->>w)::numeric>9)) then return;end if;
    for base_key in select * from app.private_invoice_word_number_value(words[1:point-1]) loop
      return next 'number:'||trim_scale((substring(base_key from 8)||'.'||(select string_agg(case when w ~ '^[0-9]+$' then w else small->>w end,'' order by n) from unnest(tail_words) with ordinality p(w,n)))::numeric)::text;
    end loop;return;
  end if;
  actual:=array_remove(array_remove(words,'and'),'a');
  if cardinality(actual)>=2 and array_position(words,'and') is null and not exists(select 1 from unnest(actual) w where not small ? w or (small->>w)::numeric>9) then
    return next 'number:'||trim_scale((select string_agg(small->>w,'' order by n) from unnest(actual) with ordinality p(w,n))::numeric)::text;return;
  end if;
  if cardinality(actual) between 2 and 3 and not exists(select 1 from unnest(actual) w where app.private_invoice_group_number(array[w]) is null) then
    part:=app.private_invoice_group_number(actual[1:1]);tail:=app.private_invoice_group_number(actual[2:cardinality(actual)]);
    if part>0 and part<100 and tail>=10 and tail<100 then return next 'number:'||trim_scale(part*100+tail)::text;return;end if;
  end if;
  -- Consecutive magnitude words form the same multiplier as in JS.
  i:=1;
  while i<=cardinality(actual) loop
    if not scales ? actual[i] then i:=i+1;continue;end if;
    start_at:=i;cluster:=1;
    while i<=cardinality(actual) and scales ? actual[i] loop
      cluster:=cluster*(scales->>actual[i])::numeric;i:=i+1;
    end loop;
    if cluster>magnitude then magnitude:=cluster;scale_start:=start_at;scale_end:=i;repeated:=false;
    elsif cluster=magnitude then repeated:=true;end if;
  end loop;
  if magnitude=0 then
    part:=app.private_invoice_group_number(actual);
    if part is not null then return next 'number:'||trim_scale(part)::text;end if;return;
  end if;
  if repeated then return;end if;factor:=magnitude;
  head:=case when scale_start=1 then array['one'] else actual[1:scale_start-1] end;
  tail_words:=case when scale_end>cardinality(actual) then array['zero'] else actual[scale_end:cardinality(actual)] end;
  for base_key in select * from app.private_invoice_word_number_value(head) loop
    for numerator_key in select * from app.private_invoice_word_number_value(tail_words) loop
      part:=substring(base_key from 8)::numeric*factor;tail:=substring(numerator_key from 8)::numeric;
      if part=trunc(part) and tail=trunc(tail) and tail<factor then return next 'number:'||trim_scale(part+tail)::text;end if;
    end loop;
  end loop;
end $$;
revoke all on function app.private_invoice_word_number_value(text[]) from public,anon,authenticated,service_role;

create function app.private_invoice_word_number_aliases(p_term text) returns setof text
language plpgsql immutable set search_path='' as $$
declare
  small jsonb:='{"zero":"0","one":"1","two":"2","three":"3","four":"4","five":"5","six":"6","seven":"7","eight":"8","nine":"9","ten":"10","eleven":"11","twelve":"12","thirteen":"13","fourteen":"14","fifteen":"15","sixteen":"16","seventeen":"17","eighteen":"18","nineteen":"19","twenty":"20","thirty":"30","forty":"40","fifty":"50","sixty":"60","seventy":"70","eighty":"80","ninety":"90"}'::jsonb; scales jsonb:='{"thousand":"1000","lakh":"100000","lac":"100000","million":"1000000","crore":"10000000","billion":"1000000000","trillion":"1000000000000","quadrillion":"1000000000000000","quintillion":"1000000000000000000"}'::jsonb; fractions jsonb:='{"half":"2","halves":"2","quarter":"4","quarters":"4","third":"3","fifth":"5","sixth":"6","seventh":"7","eighth":"8","ninth":"9","tenth":"10"}'::jsonb; magnitudes jsonb:='{"k":"thousand","m":"million","b":"billion"}'::jsonb;modifiers jsonb:='{"quartermore":{"numerator":1,"denominator":4,"base":1},"halfmore":{"numerator":1,"denominator":2,"base":1},"quarterless":{"numerator":-1,"denominator":4,"base":1}}'::jsonb;
  prepared text; normalized text; translated boolean;prior text;token text[]; word text; words text[]:=array[]::text[]; segment text[]; start_at integer:=1; end_at integer; segment_end integer; piece integer; keys text[];
begin
  -- ASCII digits and punctuation have no translated/cardinal word path.
  if p_term ~ '^[0-9 ,.''/()+-]+$' then return;end if;
  normalized:=app.private_invoice_normalize(p_term);prepared:=app.private_invoice_lexical(normalized);translated:=prepared<>normalized;
  prepared:=regexp_replace(prepared,'/[-−]$','');
  loop prior:=prepared;prepared:=btrim(regexp_replace(prepared,'^(?:'||U&'[\0024\00a2-\00a5\058f\060b\07fe-\07ff\09f2-\09f3\09fb\0af1\0bf9\0e3f\17db\20a0-\20c1\a838\fdfc\fe69\ff04\ffe0-\ffe1\ffe5-\ffe6\+011fdd-\+011fe0\+01e2ff\+01ecb0]'||'|(?:inr|usd|eur|gbp|aed|sgd|aud|cad|chf|rs\.?|rupees?|dollars?|euros?|pounds?)) *| *(?:'||U&'[\0024\00a2-\00a5\058f\060b\07fe-\07ff\09f2-\09f3\09fb\0af1\0bf9\0e3f\17db\20a0-\20c1\a838\fdfc\fe69\ff04\ffe0-\ffe1\ffe5-\ffe6\+011fdd-\+011fe0\+01e2ff\+01ecb0]'||'|(?:inr|usd|eur|gbp|aed|sgd|aud|cad|chf|rs\.?|rupees?|dollars?|euros?|pounds?))$','','g'));exit when prepared=prior;end loop;
  if prepared ~ '[a-z][0-9]' then return;end if;
  for token in select regexp_matches(prepared,'(?<![0-9/])(?:[0-9]+ +)?[0-9]+ */ *[0-9]+(?![0-9]| *[/.-] *[0-9])(?:[kmb])?|[0-9]+(?:[.,'' ]+[0-9]+)*|[a-z]+|[, &-]+|[^ ]','g') loop
    word:=token[1];
    if word ~ '^[, &-]+$' then
      if word ~ '[,&]' then words:=array_append(words,'and');end if;continue;
    end if;
    if small ? word or scales ? word or fractions ? word or magnitudes ? word or modifiers ? word or word in ('hundred','and','a','point') then
      null;
    elsif not exists(select 1 from app.private_invoice_number_aliases(word)) then
      if word ~ '[a-z]' then return;end if;word:='!';
    end if;
    words:=array_append(words,word);
  end loop;
  while start_at<=cardinality(words) loop
    segment_end:=coalesce((select min(n)::integer from unnest(words) with ordinality p(w,n) where n>=start_at and w='!'),cardinality(words)+1)-1;
    segment:=words[start_at:segment_end];piece:=1;
    if translated or exists(select 1 from unnest(segment) w where (small ? w or scales ? w or fractions ? w or magnitudes ? w or modifiers ? w or strpos(w,'/')>0 or w in ('hundred','point'))) then
      while piece<=cardinality(segment) loop
        end_at:=cardinality(segment);
        while end_at>=piece loop
          keys:=array(select k from app.private_invoice_word_number_value(segment[piece:end_at]) k);
          exit when cardinality(keys)>0;end_at:=end_at-1;
        end loop;
        if end_at<piece then piece:=piece+1;continue;end if;
        return query select unnest(keys);piece:=end_at+1;
      end loop;
    end if;
    start_at:=segment_end+2;
  end loop;
end $$;
revoke all on function app.private_invoice_word_number_aliases(text) from public,anon,authenticated,service_role;

create function app.private_invoice_shared_calendar(p_text text) returns table(value text,first_at integer,last_at integer,date_keys text[])
language plpgsql immutable set search_path='' as $$
declare groups jsonb[]:=array[]::jsonb[];active jsonb:='[]';g jsonb;items jsonb[];years jsonb[];days jsonb[];anchors jsonb;candidate jsonb;d jsonb;anchor jsonb;y jsonb;token text[];raw text;parts text[];cursor_at integer:=1;a integer;b integer;i integer;j integer;mm integer;nn integer;yy integer;own_year integer;day_num integer;day_keys text[];dt date;lo integer;hi integer;gap text;found boolean;complete boolean;prior_day jsonb;prior_key text;current_key text;alt_key text;prior_alt text;alt_date date;
begin
 if p_text !~ '(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)' and p_text !~ '[0-9] *[/.]' then return;end if;
