-- A typed projection owns declarations irrespective of field order. Nominal
-- arguments are bound to document/event roles, never every leftover word.
create function app.private_invoice_origin_projection(p_term text,p_head integer,p_proper_names jsonb) returns setof text
language plpgsql immutable set search_path='' as $$
declare document jsonb;proper_names jsonb;term text;working text;prepared text;marker text[];event_head text[];candidate text[];keys text[];prefix text[];span integer[];ranges integer[]:=array[]::integer[];n record;field text;pattern text;idx integer;a integer;b integer;cursor_at integer;label_at integer;record_at integer:=0;record_end integer:=0;doc_at integer:=0;event_at integer:=0;carrier_at integer:=0;head_at integer;head_end integer;part_index integer;limit_at integer;amount_at integer;amount_end integer;party_text text;before_value text;after_value text;raw_tail text;relation boolean;intro boolean;calendar record;
begin
