 base:=case when p_dependent then array['ை','ுக்கு','ால்','ோடு','ுடன்','ின்','ுடைய','ில்','ிடம்','ிடத்தில்','ிலிருந்து','ிடமிருந்து','ிற்கு','து','ே'] else array['ஐ','க்கு','உக்கு','ஆல்','ஓடு','உடன்','இன்','உடைய','இல்','இடம்','இடத்தில்','இலிருந்து','இடமிருந்து','இற்கு','அது','ஏ','வை','யை','வுக்கு','யுக்கு','வால்','யால்','வோடு','யோடு','வுடன்','யுடன்','வின்','யின்','வுடைய','யுடைய','வில்','யில்','விடம்','யிடம்','விடத்தில்','யிடத்தில்','விலிருந்து','யிலிருந்து','விடமிருந்து','யிடமிருந்து','விற்கு','யிற்கு','வது','யது','வே','யே'] end;
 with recursive predecessors(value) as (
  select normalize(p_tail,NFC)
  union
  select next.value from predecessors p cross join lateral (
   select left(p.value,length(p.value)-length(op)) value from unnest(array['உம்','தான்','கூட','மட்டும்','எல்லாம்','ஏ','ஓ','ஆ']) op where right(p.value,length(op))=op
   union select left(p.value,length(p.value)-length(linked)) from (select left(op,1)||'்'||op linked from unnest(array['தான்','கூட','மட்டும்']) op) f where right(p.value,length(linked))=linked and right(left(p.value,length(p.value)-length(linked)),1)='ு'
   union select left(p.value,length(p.value)-length('ம்')) where right(p.value,length('ம்'))='ம்' and right(left(p.value,length(p.value)-length('ம்')),1)='ு'
   union select left(p.value,length(p.value)-length('ும்'))||'்' where right(p.value,length('ும்'))='ும்'
   union select left(p.value,length(p.value)-length(glide)) from (values('யும்','ிீெேைஇஈஎஏஐ'),('வும்','ாூொோௌஆஊஒஓஔ')) f(glide,vowels) where right(p.value,length(glide))=glide and strpos(vowels,right(left(p.value,length(p.value)-length(glide)),1))>0
   union select left(p.value,length(p.value)-length(mark))||restore from unnest(array['ே','ோ','ா']) mark cross join unnest(array['்','ு']) restore where right(p.value,length(mark))=mark and right(left(p.value,length(p.value)-length(mark)),1) ~ '[க-ஹ]'
   union select left(p.value,length(p.value)-length(glide||mark)) from unnest(array['ே','ோ','ா']) mark cross join unnest(array['ய','வ']) glide where right(p.value,length(glide||mark))=glide||mark and right(left(p.value,length(p.value)-length(glide||mark)),1) ~ '[ாிீுூெேைொோௌ]'
  ) next where length(next.value)<=length(p.value)
 ) select exists(select 1 from predecessors where value=any(base)) into answer;return answer;
end $$;
